template <typename Iter>
auto calculate_distance(Iter first, Iter last) ->
    typename std::iterator_traits<Iter>::difference_type
{
    // Use iterator_traits::difference_type for type safety
    // typename needed because difference_type is dependent
    return std::distance(first, last);
}

// C++20 standard library equivalent (simplified for reference)
template <typename Iter>
using DiffT = typename std::iterator_traits<Iter>::difference_type;

template <typename Iter>
DiffT<Iter>
get_distance(Iter first, Iter last)
{
    return std::distance(first, last);
}
